<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/dashboard_layout.php';
$user=require_role('delivery_agent');
$summaryStatement=db()->prepare("SELECT COALESCE(SUM(total_payout),0) lifetime,COALESCE(SUM(CASE WHEN payout_status='Pending' THEN total_payout ELSE 0 END),0) pending,COALESCE(SUM(CASE WHEN payout_status='Processed' THEN total_payout ELSE 0 END),0) processed,COUNT(*) trips FROM delivery_earnings WHERE agent_id=?");$summaryStatement->execute([$user['id']]);$summary=$summaryStatement->fetch();
$statement=db()->prepare('SELECT de.*,o.tracking_code,o.quantity_liters,o.fuel_type FROM delivery_earnings de JOIN orders o ON o.id=de.order_id WHERE de.agent_id=? ORDER BY de.created_at DESC');$statement->execute([$user['id']]);$earnings=$statement->fetchAll();
dashboard_start('Earnings & Payouts','earnings',$user);
?>
<section class="welcome-panel"><div><span class="eyebrow">Earnings ledger</span><h2>Every trip. Every rupee.</h2><p>Transparent payout accounting across base fees, distance bonuses and customer tips.</p></div><span class="badge success"><?= (int)$summary['trips'] ?> completed trips</span></section>
<section class="metrics-grid"><article class="metric-card"><span class="metric-icon"><i class="fa-solid fa-chart-line"></i></span><div><strong data-counter="<?= (float)$summary['lifetime'] ?>" data-prefix="₹">₹0</strong><span>Lifetime Earnings</span></div></article><article class="metric-card"><span class="metric-icon"><i class="fa-solid fa-hourglass-half"></i></span><div><strong data-counter="<?= (float)$summary['pending'] ?>" data-prefix="₹">₹0</strong><span>Pending Payout</span></div></article><article class="metric-card"><span class="metric-icon"><i class="fa-solid fa-circle-check"></i></span><div><strong data-counter="<?= (float)$summary['processed'] ?>" data-prefix="₹">₹0</strong><span>Processed</span></div></article><article class="metric-card"><span class="metric-icon"><i class="fa-solid fa-route"></i></span><div><strong data-counter="<?= (int)$summary['trips'] ?>">0</strong><span>Completed Trips</span></div></article></section>
<section class="panel"><div class="toolbar"><input data-table-filter="#earnings-table" placeholder="Search date, order or payout status..."></div><div class="table-wrap"><table id="earnings-table"><thead><tr><th>Date</th><th>Order ID</th><th>Fuel Pumped</th><th>Base Delivery Fee</th><th>Distance Bonus</th><th>Customer Tip</th><th>Total Earned</th><th>Payout</th></tr></thead><tbody><?php foreach($earnings as $earning): ?><tr><td><?= e(date('d M Y, h:i A',strtotime($earning['created_at']))) ?></td><td><strong><?= e($earning['tracking_code']) ?></strong></td><td><?= e($earning['quantity_liters']) ?> L · <?= e($earning['fuel_type']) ?></td><td><?= money($earning['base_payout']) ?></td><td><?= money($earning['distance_bonus']) ?></td><td><?= money($earning['tip_amount']) ?></td><td class="money-tag"><?= money($earning['total_payout']) ?></td><td><span class="badge <?= status_class($earning['payout_status']) ?>"><?= e($earning['payout_status']) ?></span></td></tr><?php endforeach; ?></tbody></table></div></section>
<?php dashboard_end(); ?>
